function myPostActions(item){if(item.status==='draft')return'<a class="primary-button compact" href="#/submit">ادامه ثبت</a>';if(item.status==='published')return'<button class="secondary-button compact" data-lifecycle-action="pause">توقف موقت</button>';if(item.status==='paused')return'<button class="primary-button compact" data-lifecycle-action="resume">فعال‌کردن</button>';if(['needs_changes','rejected','expired'].includes(item.status))return'<button class="primary-button compact" data-lifecycle-action="republish">اصلاح و انتشار دوباره</button>';return''}
function renderMyPosts(){const visible=myPosts.filter(item=>item.bucket===myPostsBucket),root=document.querySelector('#my-posts');root.innerHTML=visible.map(item=>`<article class="my-post lifecycle-card" data-my-post="${item.id}"><div class="post-image ${item.image||'image-empty'}"></div><div><div class="lifecycle-title"><h3>${item.title}</h3><span class="status-pill" data-status="${item.status}">${item.statusLabel}</span></div><p>${item.meta} · نسخه ${item.version.toLocaleString('fa-IR')}</p><div class="lifecycle-actions">${myPostActions(item)}${item.status!=='draft'?'<button class="plain-action" data-lifecycle-history>تاریخچه نسخه‌ها</button><button class="plain-action" data-lifecycle-action="archive">بایگانی</button>':''}</div></div></article>`).join('');document.querySelector('#my-post-empty').hidden=visible.length>0}
