function track(event,payload={}){if(navigator.globalPrivacyControl)return;window.dataLayer=window.dataLayer||[];window.dataLayer.push({event,...payload})}
function cityLabel(){const chosen=cities.filter(city=>selectedCities.has(city.slug));return chosen.length===1?chosen[0].name:`${chosen.length} شهر`}
function updateCityLabels(){document.querySelector('#selected-city').textContent=cityLabel()}
function categoryRoot(slug){return categories.find(category=>category.slug===slug||category.children?.some(child=>child[1]===slug))}
const faNumber=value=>{const normalized=String(value??'').trim().replace(/[۰-۹]/g,digit=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)).replace(/[٬,\s]/g,'');const parsed=Number(normalized);return normalized&&Number.isFinite(parsed)?parsed:null};
function filterHref(category=listingState.category){const query=new URLSearchParams();if(listingState.query)query.set('q',listingState.query);if(listingState.minPrice!==null)query.set('min',String(listingState.minPrice));if(listingState.maxPrice!==null)query.set('max',String(listingState.maxPrice));if(listingState.photoOnly)query.set('photo','1');if(listingState.urgentOnly)query.set('urgent','1');const suffix=query.toString();return `#/search/${listingState.city||[...selectedCities][0]||'isfahan'}${category?`/${category}`:''}${suffix?`?${suffix}`:''}`}
function categoryCount(slug){const root=categoryRoot(slug);return posts.filter(post=>root&&(slug===root.slug?post.category===root.slug:post.subcategory===slug)).length}
function renderCategoryTree(){const root=categoryRoot(listingState.category);document.querySelector('#listing-categories').innerHTML=categories.map(category=>`<div><button class="${root?.slug===category.slug?'active':''}" data-list-category="${category.slug}"><span>${category.name}</span><small>${categoryCount(category.slug).toLocaleString('fa-IR')}</small></button>${root?.slug===category.slug&&category.children?`<div class="static-category-children">${category.children.map(child=>`<button class="${listingState.category===child[1]?'active':''}" data-list-category="${child[1]}"><span>${child[0]}</span><small>${categoryCount(child[1]).toLocaleString('fa-IR')}</small></button>`).join('')}</div>`:''}</div>`).join('')}
function syncFilterControls(){document.querySelector('#price-min').value=listingState.minPrice??'';document.querySelector('#price-max').value=listingState.maxPrice??'';document.querySelector('#photo-only').checked=listingState.photoOnly;document.querySelector('#urgent-only').checked=listingState.urgentOnly;document.querySelector('#mobile-price-min').value=listingState.minPrice??'';document.querySelector('#mobile-price-max').value=listingState.maxPrice??'';document.querySelector('#mobile-photo-only').checked=listingState.photoOnly;document.querySelector('#mobile-urgent-only').checked=listingState.urgentOnly}
function renderActiveFilters(){const filters=[];if(listingState.minPrice!==null)filters.push(['min',`از ${listingState.minPrice.toLocaleString('fa-IR')} میلیون`]);if(listingState.maxPrice!==null)filters.push(['max',`تا ${listingState.maxPrice.toLocaleString('fa-IR')} میلیون`]);if(listingState.photoOnly)filters.push(['photo','عکس‌دار']);if(listingState.urgentOnly)filters.push(['urgent','فوری']);const root=document.querySelector('#active-filters');root.hidden=!filters.length;root.innerHTML=filters.map(([key,label])=>`<button type="button" data-remove-filter="${key}">${label}<span aria-hidden="true">×</span></button>`).join('')+(filters.length>1?'<button type="button" class="clear-filters">پاک‌کردن همه</button>':'')}
function syncViewToggle(){document.querySelectorAll('[data-view-mode]').forEach(item=>{const active=item.dataset.viewMode===listingState.view;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active))})}
function staticMapCenter(){return staticMapCenters[listingState.city]||staticMapCenters.isfahan}
function staticMapGeoJson(result){const [lon,lat]=staticMapCenter();return {type:'FeatureCollection',features:result.map((post,index)=>({type:'Feature',id:posts.indexOf(post),properties:{postIndex:posts.indexOf(post),title:post.title},geometry:{type:'Point',coordinates:[lon+(((index*37)%17)-8)*.006,lat+(((index*23)%13)-6)*.004]}}))}}
function showStaticMapPreview(post){if(!post)return;const preview=document.querySelector('#static-map-preview');preview.querySelector('strong').textContent=post.title;preview.querySelector('span').textContent=post.price;preview.querySelector('small').textContent=post.meta;preview.hidden=false}
function syncStaticMapSource(){if(!staticMapReady)return;staticMapInstance.getSource('posts')?.setData(staticMapGeoJson(staticMapPosts));staticMapInstance.easeTo({center:staticMapCenter(),duration:0})}
function initStaticMap(){if(staticMapInstance||!window.maplibregl)return;staticMapInstance=new window.maplibregl.Map({container:'static-map-canvas',center:staticMapCenter(),zoom:11.2,style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm',type:'raster',source:'osm'}]}});staticMapInstance.on('load',()=>{staticMapInstance.addSource('posts',{type:'geojson',data:staticMapGeoJson(staticMapPosts),cluster:true,clusterRadius:52,clusterMaxZoom:14});staticMapInstance.addLayer({id:'static-post-clusters',type:'circle',source:'posts',filter:['has','point_count'],paint:{'circle-color':'#a62626','circle-radius':['step',['get','point_count'],20,20,26,100,34],'circle-stroke-color':'#fff','circle-stroke-width':2}});staticMapInstance.addLayer({id:'static-post-cluster-count',type:'symbol',source:'posts',filter:['has','point_count'],layout:{'text-field':['get','point_count_abbreviated'],'text-size':12},paint:{'text-color':'#fff'}});staticMapInstance.addLayer({id:'static-post-markers',type:'circle',source:'posts',filter:['!', ['has','point_count']],paint:{'circle-color':'#d13b3b','circle-radius':8,'circle-stroke-color':'#fff','circle-stroke-width':2}});staticMapInstance.on('click','static-post-clusters',async event=>{const feature=staticMapInstance.queryRenderedFeatures(event.point,{layers:['static-post-clusters']})[0],clusterId=Number(feature?.properties?.cluster_id),coordinates=feature?.geometry?.coordinates;if(!coordinates||!Number.isFinite(clusterId))return;const zoom=await staticMapInstance.getSource('posts').getClusterExpansionZoom(clusterId);staticMapInstance.easeTo({center:coordinates,zoom,duration:360})});staticMapInstance.on('click','static-post-markers',event=>showStaticMapPreview(posts[Number(event.features?.[0]?.properties?.postIndex)]));['static-post-clusters','static-post-markers'].forEach(layer=>{staticMapInstance.on('mouseenter',layer,()=>staticMapInstance.getCanvas().style.cursor='pointer');staticMapInstance.on('mouseleave',layer,()=>staticMapInstance.getCanvas().style.cursor='')});staticMapReady=true;document.querySelector('#static-map').classList.add('is-live');syncStaticMapSource()});staticMapInstance.on('error',()=>{if(!staticMapReady)document.querySelector('#static-map').classList.remove('is-live')});try{staticMapInstance.addControl(new window.maplibregl.NavigationControl({showCompass:false}),'top-left')}catch(error){console.warn('Map navigation control unavailable',error)}}
function renderStaticMap(result){const markers=document.querySelector('#static-map-markers');markers.innerHTML=result.map((post,index)=>`<button type="button" class="static-map-marker ${result.length>8&&index<4?'cluster':''}" style="--x:${14+(index*29)%72}%;--y:${18+(index*41)%66}%" data-map-post="${posts.indexOf(post)}" aria-label="${post.title}">${result.length>8&&index<4?Math.min(result.length-index,24):'●'}</button>`).join('');staticMapPosts=result;if(!listingState.map)return;initStaticMap();syncStaticMapSource();requestAnimationFrame(()=>staticMapInstance?.resize())}
function renderListing(){
  const root=categoryRoot(listingState.category),isChild=root&&listingState.category!==root.slug;let result=posts.filter(post=>(!root||(isChild?post.subcategory===listingState.category:post.category===root.slug))&&(!listingState.query||`${post.title} ${post.meta} ${post.price}`.includes(listingState.query))&&(listingState.minPrice===null||post.amount!==null&&post.amount>=listingState.minPrice)&&(listingState.maxPrice===null||post.amount!==null&&post.amount<=listingState.maxPrice)&&(!listingState.photoOnly||post.image)&&(!listingState.urgentOnly||post.badges.includes('فوری')));
  result=[...result].sort((a,b)=>listingState.sort==='price-asc'?(a.amount??Infinity)-(b.amount??Infinity):listingState.sort==='price-desc'?(b.amount??-1)-(a.amount??-1):posts.indexOf(a)-posts.indexOf(b));
  const shown=result.slice(0,listingState.visible), grid=document.querySelector('#search-posts');grid.classList.toggle('list-mode',listingState.view==='list');grid.innerHTML=shown.map(postMarkup).join('');grid.hidden=listingState.map;document.querySelector('#static-map').hidden=!listingState.map;document.querySelector('.listing-stage-controls').hidden=listingState.map;renderStaticMap(result);
  const selectedName=listingState.category?(categories.find(item=>item.slug===listingState.category)?.name||root?.children?.find(item=>item[1]===listingState.category)?.[0]||'آگهی‌ها'):'همه آگهی‌ها';
  document.querySelector('#listing-title').textContent=listingState.query?`نتایج «${listingState.query}»`:`${selectedName} در ${cityLabel()}`;document.querySelector('#result-count').textContent=result.length.toLocaleString('fa-IR');
  document.querySelector('#listing-empty').hidden=result.length>0;document.querySelector('#load-more').hidden=listingState.map||shown.length>=result.length;document.querySelector('#listing-pagination').hidden=listingState.map;renderCategoryTree();renderActiveFilters();syncFilterControls();syncViewToggle();
  const pages=Math.max(1,Math.ceil(result.length/6));document.querySelector('#listing-pagination').innerHTML=pages>1?Array.from({length:pages},(_,index)=>`<button type="button" data-page="${index+1}" class="${listingState.visible===(index+1)*6?'active':''}">${(index+1).toLocaleString('fa-IR')}</button>`).join(''):'';
}
function pulseListing(){document.querySelector('#listing-skeleton').hidden=false;document.querySelector('#search-posts').hidden=true;clearTimeout(loadingTimer);loadingTimer=setTimeout(()=>{document.querySelector('#listing-skeleton').hidden=true;document.querySelector('#search-posts').hidden=false;renderListing()},180)}

function renderCityDialog(filter=''){const visible=cities.filter(city=>`${city.name} ${city.province}`.includes(filter));document.querySelector('.city-list').innerHTML=visible.map(city=>`<label class="${draftCities.has(city.slug)?'selected':''}" data-city-row="${city.slug}"><input type="checkbox" data-city="${city.slug}" ${draftCities.has(city.slug)?'checked':''} ${!draftCities.has(city.slug)&&draftCities.size>=10?'disabled':''}><span><strong>${city.name}</strong><small>${city.province}</small></span></label>`).join('');document.querySelector('#selected-count').textContent=String(draftCities.size)}
function renderPopularCities(filter=''){const visible=cities.filter(city=>`${city.name} ${city.province}`.includes(filter));document.querySelector('#popular-city-grid').innerHTML=visible.map(city=>`<button type="button" data-popular-city="${city.slug}"><strong>${city.name}</strong><small>${city.province}</small><span aria-hidden="true">‹</span></button>`).join('');document.querySelector('#city-empty').hidden=visible.length>0}
