let staticChatActive='',staticChatFilter='all',staticChatBlocked=false;
function escapeChat(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function renderStaticChatList(){const query=document.querySelector('#static-chat-search').value.trim(),visible=staticChatConversations.filter(item=>(staticChatFilter==='all'||(staticChatFilter==='unread'?item.unread>0:item.context===staticChatFilter))&&(!query||`${item.peer} ${item.title} ${item.last}`.includes(query)));document.querySelector('#static-chat-list').innerHTML=visible.map(item=>`<button type="button" class="${item.id===staticChatActive?'active':''}" data-static-chat="${item.id}"><span class="static-chat-avatar" data-online="${item.online}">${item.avatar}</span><span><span><strong>${item.peer}</strong><time>${item.time}</time></span><b>${item.title}</b><small>${item.last}</small></span>${item.unread?`<em>${item.unread.toLocaleString('fa-IR')}</em>`:''}</button>`).join('');document.querySelector('#static-chat-empty').hidden=visible.length>0}
function renderStaticChatConversation(id){const conversation=staticChatConversations.find(item=>item.id===id);if(!conversation)return;staticChatActive=id;conversation.unread=0;document.querySelector('#static-chat-peer').textContent=conversation.peer;document.querySelector('#static-chat-avatar').textContent=conversation.avatar;document.querySelector('#static-chat-avatar').dataset.online=String(conversation.online);document.querySelector('#static-chat-status').textContent=conversation.online?'آنلاین':'آخرین فعالیت اخیراً';document.querySelector('#static-chat-title').textContent=conversation.title;document.querySelector('#static-chat-timeline').innerHTML=`<p class="static-chat-day">امروز</p>${(staticChatMessages[id]||[]).map(message=>`<article class="static-chat-message ${message.mine?'mine':'peer'}" data-state="${message.state}"><p>${escapeChat(message.body)}</p><footer><time>${message.time}</time>${message.mine?`<span>${message.state==='seen'?'✓✓':'✓'}</span>`:''}</footer></article>`).join('')}`;document.querySelector('.static-chat-shell').dataset.chatMobile='conversation';renderStaticChatList();requestAnimationFrame(()=>{const timeline=document.querySelector('#static-chat-timeline');timeline.scrollTop=timeline.scrollHeight})}
function renderStaticChat(requested=''){renderStaticChatList();if(requested)renderStaticChatConversation(requested)}
function readAccountValue(key,fallback){try{return JSON.parse(localStorage.getItem(`haftsoo-account-${key}`)||'null')??fallback}catch{return fallback}}
function writeAccountValue(key,value){localStorage.setItem(`haftsoo-account-${key}`,JSON.stringify(value))}
function renderStaticAccount(panel='overview'){
  const known=new Set(['overview','posts','notifications','bookmarks','recent','saved','profile','settings','notification-settings','privacy']),active=known.has(panel)?panel:'overview';
  document.querySelectorAll('[data-account-panel]').forEach(item=>item.hidden=item.dataset.accountPanel!==active);
  document.querySelectorAll('[data-account-nav]').forEach(item=>{const selected=item.dataset.accountNav===active;item.classList.toggle('active',selected);if(selected)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current')});
  const profile=readAccountValue('profile',accountDefaults.profile),preferences=readAccountValue('preferences',accountDefaults.preferences),collections=readAccountValue('collections',accountDefaults.collections),recent=readAccountValue('recent',accountDefaults.recent),saved=readAccountValue('saved',accountDefaults.saved),consents=readAccountValue('consents',accountDefaults.consents);
  document.querySelector('#static-account-name').textContent=profile.displayName;document.querySelector('#static-account-avatar').textContent=profile.displayName.trim().charAt(0)||'ه';
  const profileForm=document.querySelector('#static-profile-form');profileForm.elements.displayName.value=profile.displayName;profileForm.elements.bio.value=profile.bio;
  const preferenceForm=document.querySelector('#static-preferences-form');['theme','defaultCity','alertFrequency'].forEach(key=>preferenceForm.elements[key].value=preferences[key]);['safetyAlerts','searchAlerts','marketingMessages'].forEach(key=>preferenceForm.elements[key].checked=Boolean(preferences[key]));
  document.querySelector('#static-collections').innerHTML=collections.map(item=>`<article><span>${icon('i-bookmark')}</span><div><strong>${item.name}</strong><small>${Number(item.count||0).toLocaleString('fa-IR')} آگهی</small></div></article>`).join('');
  document.querySelector('#static-bookmark-count').textContent=collections.reduce((sum,item)=>sum+Number(item.count||0),0).toLocaleString('fa-IR');
  document.querySelector('#static-recent-list').innerHTML=recent.map(item=>`<article><div><strong>${item.title}</strong><small>${item.meta}</small></div><a href="#/post">مشاهده</a></article>`).join('')||'<p class="static-account-empty">تاریخچه بازدید خالی است.</p>';
  document.querySelector('#static-saved-list').innerHTML=saved.map(item=>`<article><div><strong>${item.name}</strong><small>${item.meta}</small></div><button class="plain-action" type="button" data-disable-saved>توقف اعلان</button></article>`).join('')||'<p class="static-account-empty">جست‌وجوی ذخیره‌شده‌ای ندارید.</p>';
  const consentForm=document.querySelector('#static-consent-form');Object.keys(consents).forEach(key=>{if(consentForm.elements[key])consentForm.elements[key].checked=Boolean(consents[key])});
  renderStaticNotifications();
}

function parseHash(){const raw=location.hash.replace(/^#\//,'')||'home';const [path,queryString='']=raw.split('?');return {parts:path.split('/'),query:new URLSearchParams(queryString)}}
function route(){const parsed=parseHash(),requested=parsed.parts[0]||'home';let current=routes.has(requested)?requested:'home';const signedIn=localStorage.getItem('haftsoo-static-auth')==='active';if(['account','chat','sessions','wallet','promotions','business','admin','analytics','risk','sre','performance','resilience'].includes(current)&&!signedIn){sessionStorage.setItem('haftsoo-auth-next',current);current='auth'}if(current==='search'){listingState.city=parsed.parts[1]||[...selectedCities][0]||'isfahan';listingState.category=parsed.parts[2]||'';listingState.query=parsed.query.get('q')||'';listingState.minPrice=faNumber(parsed.query.get('min'));listingState.maxPrice=faNumber(parsed.query.get('max'));listingState.photoOnly=parsed.query.get('photo')==='1';listingState.urgentOnly=parsed.query.get('urgent')==='1';listingState.visible=6;renderListing()}if(current==='account')renderStaticAccount(parsed.parts[1]||'overview');if(current==='chat')renderStaticChat(parsed.parts[1]||'');if(current==='sessions')renderStaticSessions();if(current==='crm')renderStaticCrm();if(current==='wallet')renderStaticWallet();if(current==='promotions')renderStaticPromotions();document.body.classList.toggle('admin-view-active',['admin','analytics','risk','sre','performance','resilience'].includes(current));document.querySelectorAll('[data-view]').forEach(view=>{view.hidden=view.dataset.view!==current});document.querySelectorAll('.bottom-nav a').forEach(link=>link.classList.toggle('active',link.hash===`#/${current}`||(current==='post'&&link.hash==='#/search')));document.title=`${({home:'بازار آگهی',search:'فهرست آگهی‌ها',post:'جزئیات آگهی',account:'هفت‌سوی من',chat:'گفتگوها',crm:'CRM و پشتیبانی',wallet:'کیف‌پول و پرداخت‌ها',finance:'عملیات مالی',promotions:'ارتقای آگهی و بسته‌ها',monetization:'مدیریت درآمدزایی',business:'کسب‌وکار من',store:'فروشگاه حرفه‌ای','business-admin':'عملیات کسب‌وکار',admin:'مرکز کنترل',analytics:'تحلیل محصول',risk:'ریسک و تقلب',sre:'SRE و رخدادها',performance:'کارایی و ظرفیت',resilience:'تاب‌آوری و بازیابی',submit:'ثبت آگهی',system:'سیستم طراحی',auth:'ورود',sessions:'دستگاه‌های فعال'})[current]} — هفت‌سو`;syncStaticAuthNav();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});document.querySelector('#main').focus({preventScroll:true})}
