document.querySelector('.static-admin-sidebar nav').addEventListener('click',event=>{const button=event.target.closest('[data-admin-section]');if(!button)return;document.querySelectorAll('[data-admin-section]').forEach(item=>item.classList.toggle('active',item===button));const panel=document.querySelector(`[data-admin-panel="${button.dataset.adminSection}"]`);panel?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});document.querySelector('.static-admin-alerts').addEventListener('click',event=>{const button=event.target.closest('button'),item=event.target.closest('[data-alert-id]');if(!button||!item)return;button.replaceWith(Object.assign(document.createElement('em'),{textContent:'در حال پیگیری'}));const message=document.querySelector('#static-admin-message');message.textContent='هشدار با نام کاربری شما تأیید و در ردپای ممیزی ثبت شد.';message.hidden=false;track('admin_alert_acknowledged',{alert:item.dataset.alertId})});document.querySelector('#static-admin-report').addEventListener('submit',event=>{event.preventDefault();const message=document.querySelector('#static-admin-message');message.textContent='گزارش در صف ساخت قرار گرفت و پس از آماده‌شدن اعلان می‌شود.';message.hidden=false;track('admin_report_requested',{kind:new FormData(event.currentTarget).get('kind')})});document.querySelector('#static-admin-config').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);try{JSON.parse(String(data.get('value')))}catch{showToast('مقدار JSON معتبر نیست');return}const message=document.querySelector('#static-admin-message');message.textContent='پیشنهاد تغییر ثبت شد؛ انتشار تولید به تأیید مدیر دوم نیاز دارد.';message.hidden=false;track('admin_configuration_proposed',{key:data.get('key'),environment:data.get('environment'),four_eyes:true})});
document.querySelector('#static-experiment-toggle').addEventListener('click',()=>{const form=document.querySelector('#static-experiment-form');form.hidden=!form.hidden;if(!form.hidden)form.querySelector('input').focus()});document.querySelector('#static-experiment-form').addEventListener('submit',event=>{event.preventDefault();const message=document.querySelector('#static-analytics-message'),data=new FormData(event.currentTarget);message.textContent='آزمایش به‌صورت پیش‌نویس ثبت شد؛ شروع آن پس از تأیید Guardrail و مدیر دوم امکان‌پذیر است.';message.hidden=false;event.currentTarget.hidden=true;track('analytics_experiment_created',{key:data.get('key'),metric:data.get('metric'),minimum_sample:Number(data.get('sample'))})});
document.querySelector('#static-risk-queue').addEventListener('click',event=>{const button=event.target.closest('[data-risk-case]');if(!button)return;document.querySelectorAll('[data-risk-case]').forEach(item=>item.classList.toggle('active',item===button));document.querySelector('#static-risk-case h2').textContent=button.querySelector('b').textContent;document.querySelector('#static-risk-message').hidden=true;track('risk_case_selected',{case_id:button.dataset.riskCase})});document.querySelector('#static-risk-claim').addEventListener('click',event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='پرونده در اختیار شماست';const message=document.querySelector('#static-risk-message');message.textContent='پرونده برای ۱۵ دقیقه به شما اختصاص یافت و در ردپای ممیزی ثبت شد.';message.hidden=false;track('risk_case_claimed',{lease_minutes:15})});document.querySelector('#static-risk-decision').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),action=data.get('action'),message=document.querySelector('#static-risk-message');message.textContent=action==='block'?'پیشنهاد مسدودسازی ثبت شد و برای تأیید مدیر دوم ارسال شد.':'تصمیم توضیح‌پذیر ثبت و برای اجرای تکرارناپذیر ارسال شد.';message.hidden=false;track('risk_case_decision',{action,four_eyes:action==='block'});showToast('تصمیم ریسک ثبت شد')});
document.querySelector('#static-sre-incidents').addEventListener('click',event=>{const button=event.target.closest('[data-sre-incident]');if(!button)return;document.querySelectorAll('[data-sre-incident]').forEach(item=>item.classList.toggle('active',item===button));document.querySelector('#static-sre-title').textContent=button.querySelector('b').textContent;document.querySelector('#static-sre-severity').textContent=button.querySelector('[data-severity]').textContent;document.querySelector('#static-sre-severity').dataset.severity=button.querySelector('[data-severity]').dataset.severity;document.querySelector('#static-sre-message').hidden=true;track('incident_selected',{incident_id:button.dataset.sreIncident})});document.querySelector('#static-sre-transition').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),next=data.get('next'),summary=data.get('summary'),timeline=document.querySelector('#static-sre-timeline'),message=document.querySelector('#static-sre-message');timeline.insertAdjacentHTML('beforeend',`<li>${summary}</li>`);message.textContent=`وضعیت رخداد به «${event.currentTarget.elements.next.selectedOptions[0].textContent}» تغییر کرد و در خط زمانی ثبت شد.`;message.hidden=false;track('incident_state_transition',{next_state:next,append_only:true});showToast('وضعیت رخداد ثبت شد')});
document.querySelector('#static-collection-form').addEventListener('submit',event=>{event.preventDefault();const field=event.currentTarget.elements.name,name=field.value.trim().slice(0,60);if(name.length<2)return;const collections=readAccountValue('collections',accountDefaults.collections);collections.push({id:crypto.randomUUID(),name,count:0});writeAccountValue('collections',collections);field.value='';renderStaticAccount('bookmarks');track('bookmark_collection_created');showToast('مجموعه نشان‌ها ساخته شد')});
document.querySelector('#static-clear-recent').addEventListener('click',()=>{writeAccountValue('recent',[]);renderStaticAccount('recent');track('recent_views_cleared');showToast('تاریخچه بازدید پاک شد')});
document.querySelector('#static-saved-list').addEventListener('click',event=>{if(!event.target.closest('[data-disable-saved]'))return;const saved=readAccountValue('saved',accountDefaults.saved).map(item=>({...item,meta:'اعلان متوقف است'}));writeAccountValue('saved',saved);renderStaticAccount('saved');showToast('اعلان جست‌وجو متوقف شد')});
document.querySelector('#static-consent-form').addEventListener('change',event=>{const form=event.currentTarget,consents={analytics:form.elements.analytics.checked,personalization:form.elements.personalization.checked,marketing:form.elements.marketing.checked};writeAccountValue('consents',consents);track('privacy_consent_recorded',{purpose:event.target.name,granted:event.target.checked});showToast('انتخاب حریم خصوصی ثبت شد')});
document.querySelector('#static-export-data').addEventListener('click',event=>{const last=Number(localStorage.getItem('haftsoo-account-export-at')||0),cooldown=24*60*60*1000;if(Date.now()-last<cooldown){showToast('درخواست خروجی قبلی در حال آماده‌سازی است');return}localStorage.setItem('haftsoo-account-export-at',String(Date.now()));event.currentTarget.disabled=true;event.currentTarget.textContent='در حال آماده‌سازی';track('account_data_export_requested');showToast('درخواست خروجی داده‌ها ثبت شد')});
document.querySelector('#static-delete-account').addEventListener('click',event=>{if(event.currentTarget.dataset.pending==='true'){event.currentTarget.dataset.pending='false';event.currentTarget.textContent='درخواست حذف حساب';localStorage.removeItem('haftsoo-account-delete-at');showToast('درخواست حذف حساب لغو شد');return}if(!confirm('حذف حساب را برای ۳۰ روز آینده زمان‌بندی می‌کنید؟'))return;const executeAt=new Date(Date.now()+30*86400000);localStorage.setItem('haftsoo-account-delete-at',executeAt.toISOString());event.currentTarget.dataset.pending='true';event.currentTarget.textContent='لغو حذف زمان‌بندی‌شده';track('account_deletion_requested');showToast(`حذف حساب برای ${executeAt.toLocaleDateString('fa-IR')} زمان‌بندی شد`)});
if(localStorage.getItem('haftsoo-account-delete-at')){const deleteButton=document.querySelector('#static-delete-account');deleteButton.dataset.pending='true';deleteButton.textContent='لغو حذف زمان‌بندی‌شده'}

const staticAuth={challenge:null,cooldown:0,timer:null};
function staticAsciiDigits(value){return[...value].map(character=>{const index='۰۱۲۳۴۵۶۷۸۹'.indexOf(character);return index<0?character:String(index)}).join('').replace(/\D/g,'')}
function syncStaticAuthNav(){const active=localStorage.getItem('haftsoo-static-auth')==='active',link=document.querySelector('.static-account-link');link.href=active?'#/account':'#/auth';link.querySelector('span').textContent=active?'هفت‌سوی من':'ورود'}
function staticAuthStep(step){document.querySelectorAll('[data-auth-step]').forEach(panel=>panel.hidden=panel.dataset.authStep!==step)}
function startStaticCooldown(){staticAuth.cooldown=30;const button=document.querySelector('#static-resend-code');button.disabled=true;clearInterval(staticAuth.timer);staticAuth.timer=setInterval(()=>{staticAuth.cooldown-=1;button.textContent=staticAuth.cooldown>0?`ارسال دوباره تا ${staticAuth.cooldown.toLocaleString('fa-IR')} ثانیه`:'ارسال دوباره';if(staticAuth.cooldown<=0){button.disabled=false;clearInterval(staticAuth.timer)}},1000)}
document.querySelector('#static-phone-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);staticAuth.challenge=crypto.randomUUID();sessionStorage.setItem('haftsoo-pre-auth',staticAuth.challenge);track('auth_otp_requested',{method:data.get('method')});staticAuthStep('otp');startStaticCooldown();document.querySelector('#static-otp-form input').focus()});
document.querySelector('#static-otp-form').addEventListener('submit',event=>{event.preventDefault();const code=staticAsciiDigits(String(new FormData(event.currentTarget).get('otp')||''));if(code.length!==6||!staticAuth.challenge){showToast('کد شش‌رقمی را کامل وارد کنید');return}localStorage.setItem('haftsoo-static-auth','active');const sessions=[{id:crypto.randomUUID(),device:'Firefox روی Windows',lastSeen:new Date().toISOString(),current:true,status:'active'},{id:crypto.randomUUID(),device:'مرورگر موبایل',lastSeen:new Date(Date.now()-86400000).toISOString(),current:false,status:'active'}];localStorage.setItem('haftsoo-static-sessions',JSON.stringify(sessions));sessionStorage.removeItem('haftsoo-pre-auth');track('auth_otp_consumed',{result:'success'});staticAuthStep('done');syncStaticAuthNav()});
document.querySelector('#static-edit-phone').addEventListener('click',()=>{staticAuth.challenge=null;staticAuthStep('phone')});document.querySelector('#static-resend-code').addEventListener('click',()=>{track('auth_otp_requested',{method:'resend'});startStaticCooldown();showToast('کد جدید درخواست شد')});
function staticSessions(){try{return JSON.parse(localStorage.getItem('haftsoo-static-sessions')||'[]')}catch{return[]}}
function renderStaticSessions(){const root=document.querySelector('#static-session-list'),sessions=staticSessions();root.innerHTML=sessions.map(session=>`<article class="static-session-card ${session.status!=='active'?'revoked':''}" data-session-id="${session.id}"><span aria-hidden="true">▰</span><div><strong>${session.device}${session.current?' · همین دستگاه':''}</strong><small>آخرین فعالیت ${new Date(session.lastSeen).toLocaleString('fa-IR')}</small></div>${session.status==='active'?'<button class="secondary-button" type="button">حذف دسترسی</button>':'<em>بسته‌شده</em>'}</article>`).join('')||'<p>نشست فعالی وجود ندارد.</p>'}
document.querySelector('#static-session-list').addEventListener('click',event=>{const card=event.target.closest('[data-session-id]'),button=event.target.closest('button');if(!card||!button)return;const sessions=staticSessions().map(session=>session.id===card.dataset.sessionId?{...session,status:'revoked'}:session);localStorage.setItem('haftsoo-static-sessions',JSON.stringify(sessions));track('auth_session_revoked',{current:sessions.find(session=>session.id===card.dataset.sessionId)?.current});renderStaticSessions();showToast('دسترسی دستگاه بسته شد')});
document.querySelector('#static-chat-search').addEventListener('input',renderStaticChatList);
document.querySelector('.static-chat-filters').addEventListener('click',event=>{const button=event.target.closest('[data-chat-filter]');if(!button)return;staticChatFilter=button.dataset.chatFilter;document.querySelectorAll('[data-chat-filter]').forEach(item=>item.classList.toggle('active',item===button));renderStaticChatList()});
document.querySelector('#static-chat-list').addEventListener('click',event=>{const button=event.target.closest('[data-static-chat]');if(!button)return;renderStaticChatConversation(button.dataset.staticChat);history.replaceState({},'',`#/chat/${button.dataset.staticChat}`)});
document.querySelector('#static-chat-back').addEventListener('click',()=>{document.querySelector('.static-chat-shell').dataset.chatMobile='inbox';history.replaceState({},'','#/chat')});
document.querySelector('#static-chat-composer').addEventListener('submit',event=>{event.preventDefault();if(staticChatBlocked||!staticChatActive)return;const input=document.querySelector('#static-chat-message'),body=input.value.replace(/\s+/g,' ').trim();if(!body)return;const now=new Date().toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}),message={mine:true,body,time:now,state:navigator.onLine?'sent':'pending'};(staticChatMessages[staticChatActive]??=[]).push(message);const conversation=staticChatConversations.find(item=>item.id===staticChatActive);conversation.last=body;conversation.time=now;input.value='';renderStaticChatConversation(staticChatActive);showToast(navigator.onLine?'پیام ارسال شد':'پیام پس از اتصال ارسال می‌شود')});
document.querySelector('#static-chat-safety').addEventListener('click',()=>{document.querySelector('#static-chat-safety-dialog').hidden=false});
document.querySelector('[data-close-chat-safety]').addEventListener('click',()=>{document.querySelector('#static-chat-safety-dialog').hidden=true});
document.querySelector('#static-chat-block').addEventListener('click',event=>{staticChatBlocked=!staticChatBlocked;event.currentTarget.textContent=staticChatBlocked?'برداشتن مسدودسازی':'مسدودکردن کاربر';document.querySelector('#static-chat-message').disabled=staticChatBlocked;showToast(staticChatBlocked?'کاربر مسدود شد':'مسدودسازی برداشته شد')});
document.querySelector('#static-chat-safety-dialog form').addEventListener('submit',event=>{event.preventDefault();document.querySelector('#static-chat-safety-dialog').hidden=true;showToast('گزارش برای بررسی ثبت شد')});
document.querySelector('#static-logout-all').addEventListener('click',()=>{localStorage.removeItem('haftsoo-static-auth');localStorage.removeItem('haftsoo-static-sessions');syncStaticAuthNav();location.hash='#/auth';showToast('از همه دستگاه‌ها خارج شدید')});
document.querySelector('#static-performance-run').addEventListener('click',event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='در صف اجرا';const message=document.querySelector('#static-performance-message');message.textContent='آزمون Smoke در محیط staging ثبت شد؛ نتیجه با بودجه انتشار مقایسه می‌شود.';message.hidden=false;track('performance_load_run',{profile:'smoke',environment:'staging',production:false});showToast('آزمون بار در صف قرار گرفت')});
document.querySelector('#static-resilience-run').addEventListener('click',event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='در صف اجرا';const message=document.querySelector('#static-resilience-message');message.textContent='آزمایش تأخیر Search با شعاع ۵٪ در staging ثبت شد؛ Abort و Rollback خودکار فعال است.';message.hidden=false;track('resilience_chaos_run',{target:'search-api',fault:'latency',environment:'staging',blast_radius_bps:500});showToast('آزمایش ایمن در صف قرار گرفت')});
